import { useState } from "react";

type Email = { id: string; subject: string; body: string };

function EmailRow({ email }: { email: Email }) {
  const [open, setOpen] = useState(false);
  return (
    <li onClick={() => setOpen(!open)}>
      {email.subject}
      {open && <p>{email.body}</p>}
    </li>
  );
}

export function Inbox({ emails }: { emails: Email[] }) {
  // Key = position: "the newest email" changes with every arrival
  return <ul>{emails.map((email, i) => <EmailRow key={i} email={email} />)}</ul>;
}

